#define S5KJN5_REG_CHIP_ID		CCI_REG16(0x0000)
#define S5KJN5_CHIP_ID			0x38e5

#define S5KJN5_REG_STREAMING		CCI_REG8(0x0100)
#define S5KJN5_STREAMING_ON		0x01
#define S5KJN5_STREAMING_OFF		0x00

#define S5KJN5_REG_FRAME_COUNT	CCI_REG8(0x0005)
#define S5KJN5_FRAME_COUNT_STANDBY	0xff
#define S5KJN5_STANDBY_POLL_ITERS	20

#define S5KJN5_REG_VTS		CCI_REG16(0x0340)
#define S5KJN5_VTS_MAX		65535

#define S5KJN5_REG_EXPOSURE	CCI_REG16(0x0202)

/* Analogue gain: linear, reg = real * 32 */
#define S5KJN5_REG_AGAIN	CCI_REG16(0x0204)
#define S5KJN5_AGAIN_MIN	0x0020	/* 1x  */
#define S5KJN5_AGAIN_MAX	0x0a00	/* 80x */

/* Digital gain: reg = real * 256 */
#define S5KJN5_REG_DGAIN	CCI_REG16(0x020e)
#define S5KJN5_DGAIN_MIN	0x0100	/* 1x  */
#define S5KJN5_DGAIN_MAX	0x1000	/* 16x */

#define S5KJN5_REG_TEST_PATTERN	CCI_REG16(0x0600)

#define S5KJN5_EXPOSURE_MIN	4
#define S5KJN5_EXPOSURE_DEFAULT	0x0100

#define S5KJN5_XVCLK_RATE	19200000

#define S5KJN5_RGB_DEPTH	10

/* Full 50.3 Mpx active pixel array */
#define S5KJN5_NATIVE_WIDTH	8192
#define S5KJN5_NATIVE_HEIGHT	6144

static const char * const s5kjn5_supply_names[] = {
	"vddio",
	"vddd",
	"vddm",
	"vdda",
	"vddio1p2",
	"afvdd",
};

struct s5kjn5_mode {
	u32 width;
	u32 height;
	u32 hts;
	u32 vts_min;
	u32 exposure_margin;
	const struct cci_reg_sequence *regs;
	u32 num_regs;
};

